      licenseUrl: "https://creativecommons.org/publicdomain/mark/1.0/",
      attribution: "Unknown English artist, 16th century. 'Portrait and Life of Chaucer', Add. MS 5141, f.1, British Library (cropped)",
      attributionUrl: "https://www.flickr.com/photos/britishlibrary/12458941013/",
