      licenseUrl: "https://creativecommons.org/publicdomain/mark/1.0/",
      attribution: "Menso Kamerlingh Onnes, Portrait of Hendrik Antoon Lorentz, 1916, oil on canvas, Icones Leidenses, Leiden University Libraries (Icones 310), public domain",
