      height: 640,
      licenseUrl: "https://creativecommons.org/publicdomain/mark/1.0/",
      attribution: "Unknown photographer, 1899, in 'Narodni album' (Prague: Jos. R. Vilimek, 1899), p. 183; National Library of the Czech Republic digital library (cropped)",
      attributionUrl: "https://ndk.cz/view/uuid:9d452470-905f-11dd-9c34-000d606f5dc6?page=uuid:a8426d20-cbba-11e6-b22f-5ef3fc9ae867",
