      attribution: "Photographer unknown, published 1942 in Horikawa Toyonaga, Kindai Nihon no kagakusha vol. 2. Source: Portraits of Modern Japanese Historical Figures, National Diet Library, Japan (https://www.ndl.go.jp/portrait/)",
      attributionUrl: "https://www.ndl.go.jp/portrait/e/datas/6356/index.html",
